<template>
 <view class="movement-library">
  <view class="section-heading"><view><text class="eyebrow">MOVEMENT / 01—10</text><text class="page-title">{{et('library')}}</text><text class="muted small">{{et('subtitle')}}</text></view><view class="movement-count"><AppIcon name="grid"/><text>10 {{et('count')}}</text></view></view>
