   <view class="movement-catalog"><view class="movement-filters"><button class="movement-filter" v-for="group in groups" :key="group" role="button" tabindex="0" :class="{selected:filter===group}" @click="filter=group">{{et(group)}}</button></view><view class="movement-grid"><button v-for="exercise in filtered" :key="exercise.slug" role="button" tabindex="0" class="movement-card" :class="{selected:selected.slug===exercise.slug}" :aria-label="et('view')+' '+exerciseName(exercise)" :aria-pressed="selected.slug===exercise.slug" @click="selected=exercise"><view class="movement-thumb"><ExerciseArt :exercise="exercise"/><view v-if="selected.slug===exercise.slug" class="movement-selected"><AppIcon name="check" tone="white"/></view></view><view class="movement-card-copy"><text class="movement-card-name">{{exerciseName(exercise)}}</text><text class="movement-card-meta">{{exerciseMeta(exercise)}}</text></view></button></view></view>
  </view>
 </view>
